// Read the rollout decision from data, not from hope.
data class RolloutHealth(val crashRate: Double, val anrRate: Double, val newTopCrashUsersPct: Double)

fun nextStep(current: Double, h: RolloutHealth): RolloutDecision = when {
    h.crashRate > 0.0109 || h.anrRate > 0.0047 || h.newTopCrashUsersPct > 0.5 -> RolloutDecision.Halt
    current < 0.05 -> RolloutDecision.Increase(0.05)
    current < 0.20 -> RolloutDecision.Increase(0.20)
    current < 0.50 -> RolloutDecision.Increase(0.50)
    else -> RolloutDecision.Increase(1.0)
}

sealed interface RolloutDecision {
    data object Halt : RolloutDecision
    data class Increase(val toFraction: Double) : RolloutDecision
}

