val releaseTag = providers.environmentVariable("GITHUB_REF_NAME")         // "v3.2.1" on tag builds
    .orElse(providers.exec { commandLine("git", "describe", "--tags", "--abbrev=0") }.standardOutput.asText.map { it.trim() })
    .map { it.removePrefix("v") }

fun codeFor(version: String): Int {
    val (major, minor, patch) = version.split(".").map(String::toInt)
    require(minor < 100 && patch < 100) { "minor and patch must be < 100" }
    return major * 10_000 + minor * 100 + patch
}

