// Server (Kotlin sketch): verify, grant, acknowledge
suspend fun verifySubscription(uid: String, productId: String, token: String): Entitlement {
    val sub = play.purchases().subscriptionsv2().get(PACKAGE, token).execute()
    require(sub.lineItems.any { it.productId == productId }) { "Wrong product" }
    val active = sub.subscriptionState in setOf("SUBSCRIPTION_STATE_ACTIVE", "SUBSCRIPTION_STATE_IN_GRACE_PERIOD")
    val expires = Instant.parse(sub.lineItems.first().expiryTime)
    val entitlement = entitlements.upsert(uid, plan = "pro", active = active, expiresAt = expires, token = token)
    if (sub.acknowledgementState == "ACKNOWLEDGEMENT_STATE_PENDING") {
        play.purchases().subscriptions().acknowledge(PACKAGE, productId, token, SubscriptionPurchasesAcknowledgeRequest()).execute()
    }
    return entitlement
}

// RTDN handler (Pub/Sub push endpoint): re-fetch state on every notification
suspend fun onDeveloperNotification(n: DeveloperNotification) {
    val token = n.subscriptionNotification?.purchaseToken ?: return
    val owner = entitlements.ownerOf(token) ?: return
    verifySubscription(owner, n.subscriptionNotification.subscriptionId, token)   // renewals, cancels, holds, refunds
}

@Composable
fun FlexibleUpdateSnackbar(checker: UpdateChecker, snackbar: SnackbarHostState) {
    val restartLabel = stringResource(R.string.restart)
    val message = stringResource(R.string.update_ready)
    LaunchedEffect(Unit) {
        checker.check(onDownloaded = {
            // called from the install listener
        })
    }
    val downloaded by checker.downloaded.collectAsStateWithLifecycle()
    LaunchedEffect(downloaded) {
        if (downloaded && snackbar.showSnackbar(message, restartLabel, duration = SnackbarDuration.Indefinite)
            == SnackbarResult.ActionPerformed) checker.completeFlexibleUpdate()
    }
}

// Review: after a success moment, at most once per few months (track it in DataStore).
suspend fun ReviewPrompt.afterOrderDelivered(activity: Activity) {
    if (!eligible(lastAskedDaysAgo = 90)) return
    val manager = ReviewManagerFactory.create(activity)
    runCatching { manager.launchReviewFlow(activity, manager.requestReviewFlow().await()).await() }
    markAsked()
}
